inputPayload.apex:
// Case 9.1 — Run Merchant Batches. Branches on the {{merchantType}} operator input (Square | Stripe).
//
// SQUARE: faithfully reproduces "Veevart Settings > Batches > Automatic Schedule > Square > Save"
// (Auctifera.AutomaticBatchScheduleController.saveHandler): (1) persists Auctifera__Schedule_Square__c
// on the Auctifera__Batch_Settings__c org default, (2) calls the GLOBAL
// Auctifera.AutomaticBatchSchedule.execute(null) to schedule the Square reconciliation jobs
// idempotently (each schedule is internally guarded by an existing-job-name check + try/catch),
// (3) arms the daily meta-scheduler cron, and (4) runs an immediate first reconciliation pass.
// STRIPE: verified no-op success-with-note. Verifies ENQUEUE/SCHEDULE (not async batch COMPLETION).
// Class/field/job names are Auctifera managed-package constants — identical in every client org.
class VerifyException extends Exception {}

final Integer BATCH_SCOPE = 200;          // PM-editable batch chunk size
final Integer LOOKBACK_MINUTES = 5;       // PM-editable: query-scoping bound for the Square snapshot/diff queries (perf only, not the verify itself)
final String SQUARE_NAMESPACE = 'Auctifera';
final Set<String> SQUARE_BATCH_CLASSES = new Set<String>{ 'SquareChargeFixBatch', 'SquareRefundBatch' };

final String MERCHANT_RAW = '{{merchantType}}';
final String MERCHANT = MERCHANT_RAW == null ? '' : MERCHANT_RAW.trim().toLowerCase();
if (MERCHANT != 'square' && MERCHANT != 'stripe') {
    throw new VerifyException('[9.1] verify failed: unrecognized merchantType \'' + MERCHANT_RAW + '\' (expected Square or Stripe)');
}

final Set<String> ACCEPTED = new Set<String>{ 'Holding', 'Queued', 'Preparing', 'Processing', 'Completed' };

if (MERCHANT == 'stripe') {
    // Snapshot the Square reconciliation AsyncApexJob Ids that ALREADY exist before the (no-op)
    // Stripe body, so the post-body check attributes only NEW rows to THIS run. A bare recency
    // window (CreatedDate >= now-N) cannot tell this run's rows from a prior Square run's rows,
    // nor from rows the recurring Square crons fire inside the same window, so a Square->Stripe
    // re-run falsely fails. Same snapshot/diff idiom as 9.3 step 2 (vnfp.ContactRolesCreationBatch).
    final DateTime since = System.now().addMinutes(-LOOKBACK_MINUTES);
    Set<Id> priorSquareJobIds = new Map<Id, AsyncApexJob>([
        SELECT Id FROM AsyncApexJob
        WHERE ApexClass.NamespacePrefix = :SQUARE_NAMESPACE
          AND ApexClass.Name IN :SQUARE_BATCH_CLASSES
          AND CreatedDate >= :since
    ]).keySet();

    // Stripe body: verified no-op — no IE-run Square batches (managed Stripe batches are always-on).

    // VERIFY: assert NO NEW Square batch job (Id not in the pre-body snapshot) was enqueued by
    // THIS run. Pre-existing / leftover / cron-fired rows are out of scope; a real regression that
    // made the Stripe branch enqueue a Square batch would still surface here as a fresh Id.
    List<AsyncApexJob> newSquare = [
        SELECT Id, ApexClass.Name FROM AsyncApexJob
        WHERE ApexClass.NamespacePrefix = :SQUARE_NAMESPACE
          AND ApexClass.Name IN :SQUARE_BATCH_CLASSES
          AND CreatedDate >= :since
          AND Id NOT IN :priorSquareJobIds
    ];
    if (!newSquare.isEmpty()) {
        throw new VerifyException('[9.1] verify failed: Stripe path must not enqueue Square batches but this run created ' + newSquare.size() + ' new Square AsyncApexJob row(s)');
    }
    System.debug(LoggingLevel.INFO, '[9.1] Stripe skipped-as-success (no Square batches to run).');
    return;
}

// ---- SQUARE path ----
// 1) Persist the durable Square auto-schedule flag (the "Square" checkbox).
Auctifera__Batch_Settings__c settings = Auctifera__Batch_Settings__c.getOrgDefaults();
if (settings == null || settings.Id == null) {
    settings = new Auctifera__Batch_Settings__c(SetupOwnerId = UserInfo.getOrganizationId());
}
settings.Auctifera__Schedule_Square__c = true;
upsert settings;

// 2) Schedule the Square jobs (idempotent) exactly like saveHandler. execute() guards each
//    schedule by existing-job-name, so a re-run is a no-op; tolerate an "already scheduled"
//    race defensively and rethrow anything else, so re-running the IC never hard-fails here.
try {
    new Auctifera.AutomaticBatchSchedule().execute(null);
} catch (Exception e) {
    if (e.getMessage() == null || !e.getMessage().toLowerCase().contains('already')) {
        throw e;
    }
    System.debug(LoggingLevel.INFO, '[9.1] execute(null) re-run no-op: ' + e.getMessage());
}

// 3) Ensure the daily meta-scheduler cron exists (re-arms the batches every day).
Integer metaCron = [SELECT COUNT() FROM CronTrigger WHERE CronJobDetail.Name = 'Veevart - Automatic Batch Schedule'];
if (metaCron == 0) {
    Auctifera.AutomaticBatchSchedule.schedule();
}

// 4) Run-now: immediate reconciliation pass for the two named batches.
Id chargeFixJobId = Database.executeBatch(new Auctifera.SquareChargeFixBatch(), BATCH_SCOPE);
Id refundJobId = Database.executeBatch(new Auctifera.SquareRefundBatch(), BATCH_SCOPE);

// VERIFY (throw => step FAILED):
//  a) durable flag is set
Auctifera__Batch_Settings__c check = Auctifera__Batch_Settings__c.getOrgDefaults();
if (check == null || check.Auctifera__Schedule_Square__c != true) {
    throw new VerifyException('[9.1] verify failed: Auctifera__Schedule_Square__c was not persisted true');
}
//  b) the schedule is armed. REQUIRED = the playbook-named batches (charge fix + refund) plus the
//     daily meta-scheduler we arm explicitly. The payment-synchronization job is also scheduled by
//     execute() but is INFORMATIONAL: it is managed-package behavior (its scheduleBatch is wrapped
//     in a swallowing try/catch and can vary by Auctifera version/payment config), so it must not
//     turn an otherwise-correct run into a false failure.
Set<String> requiredCrons = new Set<String>{
    'Veevart - Square charge fix',
    'Veevart - Square refund status update',
    'Veevart - Automatic Batch Schedule'
};
Set<String> infoCrons = new Set<String>{ 'Veevart - Square payment synchronization' };
Set<String> allWanted = new Set<String>();
allWanted.addAll(requiredCrons);
allWanted.addAll(infoCrons);
Set<String> haveCrons = new Set<String>();
for (CronTrigger ct : [SELECT CronJobDetail.Name FROM CronTrigger WHERE CronJobDetail.Name IN :allWanted]) {
    haveCrons.add(ct.CronJobDetail.Name);
}
for (String w : requiredCrons) {
    if (!haveCrons.contains(w)) {
        throw new VerifyException('[9.1] verify failed: expected scheduled job missing: ' + w);
    }
}
for (String w : infoCrons) {
    System.debug(LoggingLevel.INFO, '[9.1] info cron ' + w + ' present=' + haveCrons.contains(w));
}
//  c) the immediate run enqueued both batches in an accepted state
Map<Id, AsyncApexJob> jobsById = new Map<Id, AsyncApexJob>([
    SELECT Id, Status, ApexClass.Name FROM AsyncApexJob WHERE Id IN (:chargeFixJobId, :refundJobId)
]);
for (Id expected : new Set<Id>{ chargeFixJobId, refundJobId }) {
    AsyncApexJob job = jobsById.get(expected);
    if (job == null) {
        throw new VerifyException('[9.1] verify failed: no AsyncApexJob for immediate Square run jobId=' + expected);
    }
    if (!ACCEPTED.contains(job.Status)) {
        throw new VerifyException('[9.1] verify failed: immediate Square batch ' + job.ApexClass.Name + ' in unexpected state ' + job.Status);
    }
}
System.debug(LoggingLevel.INFO, '[9.1] verify OK - Square batches run + auto-schedule armed.');
